  ## Rubric
  Rule: The unit's responsibilities match the role of its declared layer.
  Pass: Every responsibility in the file belongs to the role and kind of its declared layer, and agrees with any ADR prose given.
  Fail: The file carries a responsibility that belongs to a different layer kind, for example persistence, transport or framework logic in a domain file, or business rules in an infrastructure or presentation file.
  Evidence required: Name the file and cite the function, method or statement that carries the misplaced responsibility, and the layer kind it belongs to.
  Out of scope: import direction and layer-dependency rules, which are checked symbolically.

  ## Source
  =====SOURCE-BEGIN src/infrastructure/dependencies.ts=====
  import { Catalog } from '../domain/Catalog';
  import { OrderRepository } from '../domain/OrderRepository';
  import { PlaceOrderUseCase } from '../application/PlaceOrderUseCase';
  import { UpdateOrderStateUseCase } from '../application/UpdateOrderStateUseCase';
  import { CancelOrderUseCase } from '../application/CancelOrderUseCase';
  import { ListOrdersByStateUseCase } from '../application/ListOrdersByStateUseCase';
  import { GetStockLevelsUseCase } from '../application/GetStockLevelsUseCase';

  export interface Dependencies {
    catalog: Catalog;
    orderRepository: OrderRepository;
    placeOrderUseCase: PlaceOrderUseCase;
    updateOrderStateUseCase: UpdateOrderStateUseCase;
    cancelOrderUseCase: CancelOrderUseCase;
    listOrdersByStateUseCase: ListOrdersByStateUseCase;
    getStockLevelsUseCase: GetStockLevelsUseCase;
  }

  export function initializeDependencies(): Dependencies {
    const catalog = new Catalog();
    const orderRepository = new OrderRepository();

    // Initialize with sample products
    catalog.addProduct({ id: 'p1', name: 'Laptop', price: 999.99 }, 10);
    catalog.addProduct({ id: 'p2', name: 'Mouse', price: 29.99 }, 50);
    catalog.addProduct({ id: 'p3', name: 'Keyboard', price: 79.99 }, 30);

    return {
      catalog,
      orderRepository,
      placeOrderUseCase: new PlaceOrderUseCase(catalog, orderRepository),
      updateOrderStateUseCase: new UpdateOrderStateUseCase(orderRepository),
      cancelOrderUseCase: new CancelOrderUseCase(catalog, orderRepository),
      listOrdersByStateUseCase: new ListOrdersByStateUseCase(orderRepository),
      getStockLevelsUseCase: new GetStockLevelsUseCase(catalog),
    };
  }

